// ListMetastoresIter returns an iterator that iterates
// over the results of ListMetastores.
//
// For example:
//
//	for item, err := range c.ListMetastoresIter(ctx, ListMetastoresRequest{}) {
//	  if err != nil {
//	    return err
//	  }
//	  fmt.Println(item)
//	}
//
// Options opts are passed to each ListMetastores call
// made by the iterator under the hood.
//
// Callers who need custom pagination logic should use
// ListMetastores directly.
func (c *internalClient) ListMetastoresIter(ctx context.Context, req ListMetastoresRequest, opts ...call.Option) iter.Seq2[*MetastoreInfo, error] {
	return func(yield func(*MetastoreInfo, error) bool) {
		// Keep pagination state local to this traversal so reusing the iterator starts
		// from the original request. Reference-bearing fields remain shared and read-only.
		pageReq := req
		for {
			resp, err := c.ListMetastores(ctx, pageReq, opts...)
			if err != nil {
				yield(nil, err)
				return
			}
			for i := range resp.Metastores {
				if !yield(&resp.Metastores[i], nil) {
					return
				}
			}
			if resp.NextPageToken == nil || *resp.NextPageToken == "" {
				return
			}
			pageReq.PageToken = resp.NextPageToken
		}
	}
}

